WoWFA_Data[1240189] = "Mastery را 3% افزایش می‌دهد و زمان کست Summon Demonic Tyrant و Summon Felguard شما را 0.5 ثانیه کاهش می‌دهد."
WoWFA_Data[1244284] = "Mastery را 2% افزایش می‌دهد."
