WoWFA_Data[1244310] = "آسیب Conflagrate را 10% افزایش می‌دهد. \n\nConflagrate اکنون $?a445465[Wither][Immolate] هدف را منفجر می‌کند و آن را تا 3 دشمن نزدیک پخش می‌کند."
WoWFA_Data[1244460] = "مدت Havoc را 5 ثانیه افزایش می‌دهد و آسیبی که قربانیان Havoc دریافت می‌کنند را 10% دیگر افزایش می‌دهد."
WoWFA_Data[1244788] = "آسیب Chaos Bolt را 5% افزایش می‌دهد و Chaos Bolt اکنون 25% شانس دارد که Incinerate بعدی شما را فوری کند."
WoWFA_En[1244877] = "Cataclysm now leaves behind a lake of fire that deals ${$1244890s1*($1244885d/$1244885t2)} Fire damage to enemies within it over $1244885d.\n\n$?a445465[Wither][Immolate] deals $1244918s1% increased damage to enemies within the lake of fire."
WoWFA_Data[1244877] = "Cataclysm اکنون دریاچه‌ای از آتش به جا می‌گذارد که طی 10 ثانیه، ${$1244890s1*($1244885d/$1244885t2)} آسیب Fire به دشمنان داخل آن وارد می‌کند.\n\n$?a445465[Wither][Immolate] به دشمنان داخل دریاچهٔ آتش، 20% آسیب بیشتری وارد می‌کند."
WoWFA_Data[1244928] = "سرعت واردکردن آسیب Rain of Fire را 25% و سرعت واردکردن آسیب Immolation Infernal شما را 10% افزایش می‌دهد."
WoWFA_Data[1244941] = "Rain of Fire 20% شانس دارد هزینهٔ Rain of Fire بعدی شما را طی 8 ثانیه به‌اندازهٔ 100% کاهش دهد."
