WoWFA_Data[1250768] = "Hand of Gul'dan اکنون 1 نفر از Wild Impهای احضارشده‌اش را تقویت می‌کند و آسیب واردشدهٔ آن‌ها را 100% افزایش می‌دهد."
WoWFA_Data[1250897] = "دیمن‌های شما به‌ازای هر دیمنی که کنترل می‌کنید، 1% آسیب بیشتری وارد می‌کنند."
