WoWFA_Data[1250921] = "Demonic Tyrant شما با زره‌ای آهنگری‌شده در Antorus تجهیز می‌شود و زره او 10% افزایش می‌یابد. در حالت احضار، Demonic Tyrant شما اکنون با حمله‌های نزدیک قدرتمند به دشمنان یورش می‌برد.\n\n Burning Cleave\nCleaves the area around the caster, inflicting $s1 Shadowflame damage to targets within 8 yds. Damage reduced beyond 8 targets."
WoWFA_Data[1251778] = "Call Dreadstalkers همچنین یک Vilefiend احضار می‌کند که برای 15 ثانیه در نبرد به شما کمک می‌کند."
WoWFA_En[1257052] = "Consume the life force of each target afflicted by your damaging periodic effects, dealing ${$1257065s1*(1+ $d/$t1)} Shadowflame damage over $d.\n\nDamage dealt by Dark Harvest heals you for ${$1257065e1*100}% of damage done."
WoWFA_Data[1257052] = "نیروی حیاتی هر هدفِ تحت اثرات دوره‌ای آسیب‌زنندهٔ شما را مصرف می‌کند و طی 3 ثانیه، ${$1257065s1*(1+ $d/$t1)} آسیب Shadowflame وارد می‌کند.\n\nآسیب واردشده توسط Dark Harvest، به‌میزان 50% از آسیب انجام‌شده به شما شفا می‌دهد."
WoWFA_En[1259790] = "Afflicts the target with $o2 Shadow damage over $d. Multiple uses of this ability may overlap.\n\nIf dispelled, deals ${$m2*$s1/100} damage to the dispeller and silences them for $196364d. This damage is increased by $s3% per stack on the target.\n\n|cFFFFFFFFGenerates $231791m1 Soul $LShard:Shards; if the target dies while afflicted.|r"
WoWFA_Data[1259790] = "هدف را طی 8 ثانیه با $o2 آسیب Shadow مبتلا می‌کند. چندین استفاده از این توانایی می‌تواند هم‌پوشانی داشته باشد.\n\nاگر دفع شود، به دفع‌کننده ${$m2*$s1/100} آسیب می‌زند و او را برای 4 ثانیه سایلنت می‌کند. این آسیب به‌ازای هر استک روی هدف، 15% افزایش می‌یابد.\n\n|cFFFFFFFFاگر هدف در حالت مبتلا بمیرد، 1 Soul Shard تولید می‌کند.|r"
WoWFA_Data[1259811] = "Mastery به‌اندازهٔ 2% افزایش می‌یابد."
WoWFA_Data[1259815] = "آسیب Unstable Affliction و Seed of Corruption را 5% افزایش می‌دهد."
WoWFA_Data[1259825] = "آسیب Agony را 10% افزایش می‌دهد و Agony اکنون به دشمن دیگری در فاصلهٔ 15 یاردی هدف نیز می‌خورد."
WoWFA_Data[1259838] = "زمان کست Seed of Corruption را 0.2 ثانیه کاهش می‌دهد و آسیب آن را 5% افزایش می‌دهد."
WoWFA_Data[1259886] = "کست کردن Unstable Affliction یا Seed of Corruption، کول‌داون Dark Harvest را 1.5 ثانیه کاهش می‌دهد."
WoWFA_Data[1260209] = "آسیب Agony 10% افزایش می‌یابد و با 3 استک شروع می‌شود."
WoWFA_Data[1260229] = "وقتی Unstable Affliction تمام می‌شود، 10% شانس دارد خودش را دوباره اعمال کند."
WoWFA_En[1260264] = "Damage dealt by $?s388667[Drain Soul][Shadow Bolt] has a $?s198590[$s1][$s2]% chance to make your next Unstable Affliction or Seed of Corruption cost no Soul Shards and cast instantly."
WoWFA_Data[1260264] = "آسیب $?s388667[Drain Soul][Shadow Bolt]، $?s198590[10][20]% شانس دارد که Unstable Affliction یا Seed of Corruption بعدی شما را بدون مصرف Soul Shard و کست فوری کند."
WoWFA_Data[1261124] = "کست کردن Unstable Affliction روی هدفی که خود تحت Unstable Affliction شماست، Haste شما را برای 15 ثانیه به‌اندازهٔ 5% افزایش می‌دهد."
WoWFA_En[1261149] = "While Darkglare is active, your $?a388667[Drain Soul][Shadow Bolt] becomes Malefic Grasp. \n\n$@spellicon1261153 $@spellname1261153\n$@spelldesc1261153"
WoWFA_Data[1261149] = "وقتی Darkglare فعال است، $?a388667[Drain Soul][Shadow Bolt] شما به Malefic Grasp تبدیل می‌شود. \n\n Malefic Grasp\nBinds the target in twilight, dealing $o1 Shadow damage over 4 ثانیه.\n\nWhen Malefic Grasp deals damage, it causes all of your other periodic Affliction damage effects to instantly deal 30% of their normal periodic damage."
WoWFA_En[1261984] = "Haunt now calls upon a demonic soul from within the Twisting Nether to haunt your target.\n\nThe soul is unstable and ravenous, dealing ${$1262710s1*($48181d/$48181t5)} Shadow damage to its host and ${$1262710x1-1} enemies within $1278047a1 yards suffering from your $?a445465[Wither][Corruption] over its duration."
WoWFA_Data[1261984] = "Haunt اکنون روحی دیمنی را از درون Twisting Nether فرامی‌خواند تا هدف شما را تسخیر کند.\n\nاین روح ناآرام و شکم‌سیر است و در طول مدت خود، به میزبان و 3 دشمنِ در فاصلهٔ 10 یاردیِ تحت $?a445465[Wither][Corruption] شما، ${$1262710s1*($48181d/$48181t5)} آسیب Shadow وارد می‌کند."
WoWFA_Data[1261990] = "آسیب اولیهٔ Haunt را 50% افزایش می‌دهد و Haunt آسیب واردشده به میزبان را 2% دیگر افزایش می‌دهد."
WoWFA_En[1261992] = "Damage dealt by Haunt has a chance to release the demonic soul haunting its target. When released, it unleashes a devastating attack before being banished back to Nathreza.\n\n$@spellicon1262028 $@spellname1262028\n$@spelldesc1262028"
WoWFA_Data[1261992] = "آسیب Haunt شانس دارد روح دیمنیِ تسخیرکنندهٔ هدف را آزاد کند. روح پس از آزادشدن، حمله‌ای ویرانگر انجام می‌دهد و سپس به Nathreza تبعید می‌شود.\n\n Wrath of Nathreza\nCalls down a meteor formed from the ruins of Nathreza that explodes upon impact, dealing $1278047s1 Shadow damage to all enemies within 10 yds.\n\nDamage reduced beyond 8 targets."
WoWFA_Data[1263935] = "کول‌داون Felstorm Felguard شما به‌اندازهٔ 10 ثانیه کاهش می‌یابد و آسیبی که به دیمن اصلی شما وارد می‌شود 10% کاهش می‌یابد."
WoWFA_Data[1263941] = "وقتی Wild Impهای شما Fel Firebolt کست می‌کنند، 10% شانس دارند فوراً Fel Firebolt دیگری با اثربخشی 200% کست کنند."
WoWFA_Data[1265770] = "کست کردن Incinerate، 10% شانس دارد بازتابی از قدرت تیتان تاریک را فرابخواند.\n\n Echo of Sargeras\nHurl an ember torn from Nihilam at the target, dealing 10 Shadowflame damage and an additional 10 Shadowflame damage to all enemies within 10 yds.\n\nDamage reduced beyond 8 targets."
WoWFA_Data[1265772] = "وقتی قدرت تیتان تاریک را فرامی‌خوانید، خاطرات ویرانی تیتان‌ها در ذهنتان درخشیده و برای 6 ثانیه، Critical Strike را 4% و Haste را 4% افزایش می‌دهد."
WoWFA_En[1265774] = "Casting Chaos Bolt, Shadowburn, or Rain of Fire evokes an echo of the Dark Titan's power at $s1%, $s2%, or $s3% effectiveness respectively.\n\nIf no target is found, a random target suffering from your $?a445465[Wither][Immolate] will be selected."
WoWFA_Data[1265774] = "کست کردن Chaos Bolt، Shadowburn یا Rain of Fire، به‌ترتیب با اثربخشی 50%، 50% یا 60%، بازتابی از قدرت تیتان تاریک را فرامی‌خواند.\n\nاگر هدفی پیدا نشود، هدفی تصادفی که تحت $?a445465[Wither][Immolate] شماست انتخاب می‌شود."
WoWFA_Data[1265799] = "Call forth a cloud of cloying shadow mist that envelopes the target and all enemies within 10 yds, increasing the time between their attacks by 100% and reducing their critical strike chance by 10% for 12 ثانیه.\n\n|cFF8282FFCurses: A warlock can only have one Curse or Blight active per target.|r"
WoWFA_Data[1265801] = "زمان کست Demonic Gateway را 0.5 ثانیه کاهش می‌دهد و اکنون می‌توانید پیش از فعال‌شدن کول‌داون، دو بار از Demonic Gateway استفاده کنید."
WoWFA_Data[1265810] = "شفای Drain Life همچنین با اثربخشی 400% دیمن اصلی شما را شفا می‌دهد."
WoWFA_En[1265813] = "Casting Curse of Exhaustion, Curse of Tongues, or $?a440057[Curse of the Satyr][Curse of Weakness] now curses all enemies within $s1 yds of the target."
WoWFA_Data[1265813] = "کست کردن Curse of Exhaustion، Curse of Tongues یا $?a440057[نفرین Curse of the Satyr][نفرین Curse of Weakness]، اکنون تمام دشمنان در فاصلهٔ 10 یاردی هدف را نیز نفرین می‌کند."
WoWFA_Data[1265816] = "برد Mortal Coil را 10 یارد افزایش می‌دهد و Mortal Coil اکنون 5% دیگر از حداکثر سلامتی نیز شفا می‌دهد."
WoWFA_En[1266799] = "Increases the damage of $?a137043[Unstable Affliction by $s1][Chaos Bolt by $s4]% and $?a137043[Seed of Corruption by $s3][Rain of Fire by $s5]%.\n\nThis effect is doubled while Malevolence is active."
WoWFA_Data[1266799] = "آسیب $?a137043[Unstable Affliction را 8][Chaos Bolt را 35]% و $?a137043[Seed of Corruption را 4][Rain of Fire را 6]% افزایش می‌دهد.\n\nاین اثر وقتی Malevolence فعال است، دو برابر می‌شود."
WoWFA_Data[1266803] = "Malevolence 4% Haste اضافی می‌دهد و هنگام کست، تعداد استک Witherهای فعال را 2 استک دیگر افزایش می‌دهد."
WoWFA_Data[1266805] = "آسیب دوره‌ای Wither شانس دارد که به‌مدت 8 ثانیه Malevolence اعطا کند."
WoWFA_En[1268709] = "You summon a Diabolic Oculus, up to $1269643u, each time the duration of Diabolic Ritual is reduced by one of your spells.\n\nDiabolic Oculi explode when consuming Demonic Art, dealing $1269800s1 Fire damage to all enemies within $1269800a1 yds of the target. Damage reduced beyond $s1 targets."
WoWFA_Data[1268709] = "هر بار که مدت Diabolic Ritual توسط یکی از اسپل‌های شما کاهش یابد، یک Diabolic Oculus احضار می‌کنید؛ تا سقف 3.\n\nDiabolic Oculi هنگام مصرف Demonic Art منفجر می‌شوند و $1269800s1 آسیب Fire به تمام دشمنان در فاصلهٔ 10 یاردی هدف وارد می‌کنند. آسیب پس از 8 هدف کاهش می‌یابد."
WoWFA_En[1268713] = "Your Diabolic Oculi now cast Diabolic Gaze at your primary demon's target every 1 sec while active.\n\n$@spellicon1269892 $@spellname1269892\n$@spelldesc1269892"
WoWFA_Data[1268713] = "Diabolic Oculi شما در طول فعال‌بودن، اکنون هر 1 ثانیه یک Diabolic Gaze به هدف دیمن اصلی شما کست می‌کنند.\n\n Diabolic Gaze\nFire a beam of destructive chaos magic at the target, dealing $s1 Chaos damage.\n\nDamage is increased by 100% per Demonic Oculus active."
WoWFA_Data[1268716] = "Diabolic Oculi شما میدان نبرد را رصد می‌کنند و اطلاعاتی جمع می‌کنند که هنگام انفجار به شما منتقل می‌شود؛ هر Diabolic Oculus، Intellect شما را برای 10 ثانیه به‌اندازهٔ 2% افزایش می‌دهد."
WoWFA_En[1268884] = "Each Succulent Soul consumed has an increasing chance to unleash the Demonic Soul within you, enabling it to assault your enemies for $1269042d.\n\n$@spellicon1269049 $@spellname1269049\n$@spelldesc1269049"
WoWFA_Data[1268884] = "هر Succulent Soul مصرف‌شده، شانس فزاینده‌ای دارد که Demonic Soul درون شما را آزاد کند تا برای 9 ثانیه به دشمنان شما یورش ببرد.\n\n Soul Swipe\nStrikes nearby enemies with a malevolent claw, dealing $s1 Shadow damage to its target and $s2 Shadow damage to other enemies in 10 yds."
WoWFA_Data[1268889] = "Mastery شما را 2% افزایش می‌دهد.\n\nاین اثر وقتی موجود دیمنی در نبرد به شما کمک می‌کند، دو برابر می‌شود."
WoWFA_Data[1268903] = "مدت Manifested Avarice را 5 ثانیه افزایش می‌دهد و آسیب Soul Swipe را 10% افزایش می‌دهد."
WoWFA_Data[1270255] = "کول‌داون Shadowfury را به‌اندازهٔ 15 ثانیه کاهش می‌دهد و شعاع آن را 2 یارد افزایش می‌دهد.\n\nکول‌داون Howl of Terror را به‌اندازهٔ 5 ثانیه کاهش می‌دهد و اکنون 5 دشمن دیگر را نیز می‌ترساند."
WoWFA_Data[1270690] = "Leech شما را 2% افزایش می‌دهد."
WoWFA_Data[1270691] = "Haste شما را 2% افزایش می‌دهد."
WoWFA_Data[1270693] = "شانس Critical Strike شما را 2% افزایش می‌دهد."
WoWFA_Data[1270695] = "Intellect شما را 3% افزایش می‌دهد."
WoWFA_Data[1270701] = "Drain Life اکنون 100% سریع‌تر کانال می‌شود و 100% سریع‌تر سلامتی بازیابی می‌کند."
WoWFA_Data[1271689] = "Drain Life 200% شفای اضافی بر اساس آسیب واردشده می‌دهد و به‌میزان 10% آسیب واردشده، Soul Leech اعطا می‌کند."
WoWFA_Data[1271694] = "Soul Leech اکنون می‌تواند 5% حداکثر سلامتی شما را بیشتر جذب کند."
WoWFA_Data[1271699] = "Healthstoneها 5% سلامتی اضافی بیشتری به شما شفا می‌دهند."
WoWFA_Data[1271802] = "ابر مه سایه‌ای خفه‌کننده را فرامی‌خوانید که هدف و تمام دشمنان در فاصلهٔ 10 یاردی را در بر می‌گیرد و زمان کست تمام اسپل‌هایشان را برای 12 ثانیه به‌اندازهٔ 100% افزایش می‌دهد.\n\n|cFF8282FFCurses: یک warlock فقط می‌تواند یک Curse یا Blight فعال روی هر هدف داشته باشد.|r"
WoWFA_Data[1276163] = "احضار Demonic Tyrant، برای 15 ثانیه دروازه‌ای به Argus باز نگه می‌دارد؛ به‌طوری که هر 2 بار کست Hand of Gul'dan، دیمنی مطیع احضار می‌کند که برای 10 ثانیه به شما خدمت می‌کند."
WoWFA_Data[1276190] = "مدت Dominion of Argus را 5 ثانیه افزایش می‌دهد و آسیب Hand of Gul'dan را 10% افزایش می‌دهد."
WoWFA_Data[1276222] = "وقتی Dominion of Argus فعال است، Hand of Gul'dan 1 Soul Shard بازمی‌گرداند.\n\nدیمن‌های احضارشده توسط Dominion of Argus، 4 ثانیه بیشتر دوام می‌آورند."
WoWFA_Data[1276433] = "آسیب Hand of Gul'dan به هدف اصلی‌اش را 20% افزایش می‌دهد."
WoWFA_Data[1276452] = "یک Imp Lord احضار می‌کند که برای 20 ثانیه در نبرد به شما کمک می‌کند و هنگام احضار، 1 اثر مضر را از شما حذف می‌کند. \n\nدر طول کول‌داون به Singe Magic تبدیل می‌شود."
WoWFA_Data[1276467] = "یک Fel Ravager احضار می‌کند که برای 20 ثانیه در نبرد به شما کمک می‌کند و 1 اثر جادویی سودمند را از دشمنی پاک می‌کند.\n\nدر طول کول‌داون به Devour Magic تبدیل می‌شود."
WoWFA_Data[1276661] = "مدت Summon Vilefiend، Grimoire: Imp Lord و Grimoire: Fel Ravager شما را 3 ثانیه افزایش می‌دهد."
WoWFA_En[1276672] = "Summons a Doomguard to assist you in combat for $d. Consuming a Demonic Core reduces the cooldown of Summon Doomguard by $s2 sec.\n\n$@spellicon1251989 $@spellname1251989\n$@spelldesc1251989"
WoWFA_Data[1276672] = "یک Doomguard احضار می‌کند که برای 12 ثانیه در نبرد به شما کمک می‌کند. مصرف Demonic Core، کول‌داون Summon Doomguard را 3 ثانیه کاهش می‌دهد.\n\n Doom Bolt Volley\nSends a volley of malefic bolts at 5 enemies within 40 yds, inflicting $s1 Shadow damage to each target."
WoWFA_Data[1276746] = "Demonic Tyrant شما در طول فعال‌بودن، شما را نیز تقویت می‌کند و Haste شما را 8% افزایش می‌دهد."
WoWFA_Data[1276748] = "Demonic Tyrant شما 5 ثانیه بیشتر دوام می‌آورد و هنگام احضار، مدت Dreadstalkerهای شما را 15 ثانیه تمدید می‌کند."
WoWFA_Data[1276947] = "Call Dreadstalkers 1 Soul Shard کمتر مصرف می‌کند و زمان کست آن 50% کاهش می‌یابد."
WoWFA_Data[1276956] = "دندان‌های Dreadstalkerهای شما با زهرآب خورنده آغشته شده است و باعث می‌شود Dreadbite به‌اندازهٔ 50% از آسیب واردشده، آسیب Plague اضافی وارد کند."
WoWFA_En[1279510] = "Increases damage dealt by Agony and $?a445465[Wither][Corruption] by $s1%."
WoWFA_Data[1279510] = "آسیب Agony و $?a445465[Wither][Corruption] را 10% افزایش می‌دهد."
WoWFA_Data[1279521] = "مدت Summon Darkglare را 5 ثانیه افزایش می‌دهد."
WoWFA_Data[1279575] = "آسیب Felstorm Felguard شما را 20% و مدت آن را 4 ثانیه افزایش می‌دهد."
WoWFA_Data[1280483] = "کول‌داون Summon Infernal را 30 ثانیه کاهش می‌دهد و Mastery شما را 3% افزایش می‌دهد."
WoWFA_Data[1280733] = "Darkglare شما را با زره‌ای آهنگری‌شده از درون Antorus می‌آراید و زره او را 10% افزایش می‌دهد. \n\nEye Beam اکنون به تا 4 هدف دیگر در فاصلهٔ 10 یاردی جهش می‌کند و 10% آسیب بیشتری وارد می‌کند."
WoWFA_En[1280868] = "Chaos Bolt and Shadowburn have a $s1% chance to rip open a hole in space and time, opening a random portal that damages your target:\n\n$@spellicon394235$@spellname394235\n$@spelldesc394235\n\n$@spellicon387979$@spellname387979\n$@spelldesc387979\n\n$@spellicon394243$@spellname394243\n$@spelldesc394243\n\n|cFFFFFFFFGenerates $s2 Soul Shard Fragments.|r"
WoWFA_Data[1280868] = "Chaos Bolt و Shadowburn 10% شانس دارند در فضا و زمان شکافی بگشایند و درگاهی تصادفی باز کنند که به هدف شما آسیب می‌زند:\n\nShadowy Tear\nDeals ${$394238s1*($394237d/$394237t1)} Shadow damage over 14 ثانیه.\n\nUnstable Tear\nDeals ${$387985s1*($387984d/$387984t1)} Chaos damage over 6 ثانیه.\n\nChaos Tear\nFires a Chaos Bolt, dealing 1 Chaos damage. This Chaos Bolt always critically strikes and your critical strike chance increases its damage.\n\n|cFFFFFFFF10 Soul Shard Fragment تولید می‌کند.|r"
WoWFA_Data[1281511] = "Power Siphon و Implosion به‌ازای هر 2 Wild Imp قربانی‌شده، 1 Imp Gang Boss احضار می‌کنند. Wild Impهایی که این‌طور احضار می‌شوند، Unstable Soul می‌گیرند.\n\n Unstable Soul\nIncreases damage done by 50% and Fel Firebolt now jumps to 4 additional targets."
WoWFA_En[1311653] = "All single-target damage done by you and your minions grants you and your pet shadowy shields that absorb $s1% of the damage dealt$?s219272[][ for $108366d], up to $s2% of maximum health."
WoWFA_Data[1311653] = "تمام آسیب تک‌هدفی که شما و مینیون‌هایتان وارد می‌کنید، به شما و دیمنتان سپرهای سایه‌ای می‌دهد که 3% از آسیب واردشده را جذب می‌کنند$?s219272[][ و 15 ثانیه دوام دارند]؛ تا سقف 5% حداکثر سلامتی."
WoWFA_Data[1311969] = "آسیب Drain Life را 10% افزایش می‌دهد و Siphon Life اکنون آسیب Corruption را 10% دیگر افزایش می‌دهد.\n\nDark Harvest 10% سریع‌تر کانال می‌شود و 15% آسیب بیشتری وارد می‌کند."
WoWFA_En[1312998] = "$?a388667[Drain Soul][Shadow Bolt] and Malefic Grasp damage increased by $s1% or $s2% if the target is affected by Haunt. \n\nDark Harvest damage increased by $s3% or $s4% if the target is affected by Haunt."
WoWFA_Data[1312998] = "آسیب $?a388667[Drain Soul][Shadow Bolt] و Malefic Grasp 10% و اگر هدف تحت Haunt باشد، 20% افزایش می‌یابد. \n\nآسیب Dark Harvest 10% و اگر هدف تحت Haunt باشد، 20% افزایش می‌یابد."
